// === Tab: mySketch.js ===
// by SamuelYAN
// more works //
// https://twitter.com/SamuelAnn0924
// https://www.instagram.com/samuel_yan_1990/

// Shape of TIME


let scale;
let t;

// colors without alpha
const palettes = [
	["#4596c7", "#6d8370", "#e45240", "#21d3a4", "#3303f9"],
	["#5d565c", "#b41a1d", "#c0dee4", "#edb136", "#e07958"],
	["#7382ce", "#9fb7f4", "#12177d", "#9bb5e9", "#7486af"],
	["#1b1b1b", "#292929", "#f3f3f3", "#222222", "#ff0000"],
	["#eda492", "#d59c95", "#af3918", "#d9b6b5", "#853532"],
	["#f86fcd", "#97d183", "#240ce8", "#b0e298", "#7f37e8"],
	["#2E294E", "#541388", "#F1E9DA", "#FFD400", "#D90368"]
]

/** OPC START **/
OPC.slider('Seed', 88, 0, 100, 1);
OPC.slider('Nebula_Rings', 100, 50, 150, 10);
OPC.slider('Star_Amount', 150, 50, 200, 10);
OPC.slider('Nebula_Color', 4, 0, palettes.length - 1, 1);
OPC.slider('Turbulence', 4.25, 0.25, 6, 0.25);
OPC.slider('Nebula_Size', 800, 500, 1000, 50);
OPC.slider('Stars_Size', 5, 3, 8, 1);
OPC.slider('Nebula_Roll', 1.5, 0, 12, 0.5);
/** OPC END **/

let Pseed = Seed;
let PNebula_Rings = Nebula_Rings;
let PNebula_Color = Nebula_Color;
let PTurbulence = Turbulence;
let PNebula_Size = Nebula_Size;
let PNebula_Roll = Nebula_Roll;
let PStars_Size = Stars_Size;

function setup() {
	randomSeed(Seed);
	noiseSeed(Seed);
	createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 360, 100, 100, 100);
	background(10);
	noFill();
	scale = 1;
}

function draw() {
	randomSeed(Seed);
	noiseSeed(Seed);
	background(10);
	push();
	translate(width / 2, height / 2);
	let o_angle = random(TAU);

	for (let r = 0; r < Nebula_Size; r += Nebula_Size / Nebula_Rings) {
		stroke(random(palettes[Nebula_Color]));
		strokeCap(ROUND);
		rotate(o_angle + Nebula_Roll);

		// blendMode(LIGHTEST);
		for (
			let a = -TAU / Star_Amount; a < TAU + TAU / Star_Amount; a += TAU / Star_Amount
		) {
			let x = r * cos(a);
			let y = r * sin(a);
			let n = map(noise(x * (Turbulence/1000), y * (Turbulence/1000)), 0, 1, -scale, scale);
			stroke(random(palettes[Nebula_Color]));
			strokeWeight(n * Stars_Size);
			point(x * n, y * n);
			strokeWeight(n * Stars_Size);
			point(x * (1 - n), y * (1 - n));

		}
	}
	pop();
	change_opc();
}

function change_opc() {
	if (Pseed != Seed ||
		PNebula_Rings != Nebula_Rings ||
		PNebula_Color != Nebula_Color ||
		PTurbulence != Turbulence ||
		PNebula_Size != Nebula_Size ||
		 PNebula_Roll != Nebula_Roll ||
		 PStars_Size != Stars_Size) {

		Pseed = Seed;
		PNebula_Rings = Nebula_Rings;
		PNebula_Color = Nebula_Color;
		PTurbulence = Turbulence;
		PNebula_Size = Nebula_Size;
		PNebula_Roll =Nebula_Roll;
		PStars_Size = Stars_Size;

		randomSeed(Seed);
	noiseSeed(Seed);
	background(10);
	}
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("Shape of TIME_nebula", "png");
	}
}

